  return <><SectionHeader eyebrow="Live inventory" title={role === 'student' ? 'My room details' : 'Room management'} description={role === 'student' ? 'View your assigned room, occupancy, amenities, and fee information.' : 'Track room capacity, occupancy, availability, fees, and maintenance status.'} action={role !== 'student' && <PrimaryButton onClick={() => openForm()}><Plus size={17} /> Add room</PrimaryButton>} /><Card className="p-4"><div className="flex flex-col gap-3 sm:flex-row"><SearchBox value={search} onChange={setSearch} placeholder="Search block, room, status…" /><div className="ml-auto flex items-center gap-2 text-sm font-bold text-slate-500"><Filter size={16} /> {rows.length} rooms</div></div></Card>{api.loading ? <SmallLoader /> : api.error ? <div className="mt-5"><ErrorBanner message={api.error} retry={api.refresh} /></div> : rows.length ? <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">{rows.map((room) => { const pct = Math.round(room.occupied/room.capacity*100); return <motion.div whileHover={{ y: -4 }} key={room.id}><Card className="overflow-hidden"><div className={`h-1.5 ${room.status === 'Maintenance' ? 'bg-amber-400' : room.occupied >= room.capacity ? 'bg-rose-400' : 'bg-emerald-400'}`} /><div className="p-5"><div className="flex items-start justify-between"><div><div className="text-xs font-extrabold uppercase tracking-wider text-slate-400">{room.block} · Floor {room.floor}</div><div className="mt-1 text-2xl font-black">Room {room.room_no}</div></div><StatusBadge value={room.status} /></div><div className="mt-5 rounded-xl bg-slate-50 p-3 dark:bg-white/[.035]"><div className="flex justify-between text-xs font-bold"><span>Occupancy</span><span>{room.occupied} / {room.capacity} beds</span></div><div className="mt-2 h-2 rounded-full bg-slate-200 dark:bg-white/10"><div className={`h-full rounded-full ${pct >= 100 ? 'bg-rose-500' : 'bg-indigo-500'}`} style={{width:`${Math.min(pct,100)}%`}} /></div></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><div className="text-slate-400">Room type</div><div className="mt-1 font-extrabold">{room.type}</div></div><div><div className="text-slate-400">Monthly fee</div><div className="mt-1 font-extrabold">₹{Number(room.monthly_fee).toLocaleString('en-IN')}</div></div></div><div className="mt-4 flex flex-wrap gap-1.5">{(room.amenities || []).map((item: string) => <span key={item} className="rounded-md bg-indigo-50 px-2 py-1 text-[10px] font-bold text-indigo-600 dark:bg-indigo-500/10 dark:text-indigo-300">{item}</span>)}</div>{role !== 'student' && <div className="mt-5 flex gap-2 border-t border-slate-100 pt-4 dark:border-white/[.06]"><button onClick={() => openForm(room)} className="flex flex-1 items-center justify-center gap-2 rounded-lg bg-slate-100 px-3 py-2 text-xs font-extrabold hover:bg-indigo-50 hover:text-indigo-600 dark:bg-white/5"><Pencil size={13} /> Edit</button><button onClick={() => remove(room.id)} className="icon-button hover:text-rose-600"><Trash2 size={15} /></button></div>}</div></Card></motion.div>; })}</div> : <EmptyState icon={BedDouble} />}
  <Modal open={modal} onClose={() => setModal(false)} title={editing ? 'Edit room' : 'Add hostel room'}><form onSubmit={save}><div className="grid gap-4 sm:grid-cols-2"><Field label="Block"><input className={inputClass} value={form.block} onChange={(e) => setForm({...form,block:e.target.value})} /></Field><Field label="Room number"><input className={inputClass} value={form.room_no} onChange={(e) => setForm({...form,room_no:e.target.value})} /></Field><Field label="Floor"><input type="number" className={inputClass} value={form.floor} onChange={(e) => setForm({...form,floor:e.target.value})} /></Field><Field label="Room type"><select className={inputClass} value={form.type} onChange={(e) => setForm({...form,type:e.target.value})}><option>Single</option><option>Double Sharing</option><option>Triple Sharing</option><option>Four Sharing</option></select></Field><Field label="Capacity"><input type="number" className={inputClass} value={form.capacity} onChange={(e) => setForm({...form,capacity:e.target.value})} /></Field><Field label="Occupied beds"><input type="number" className={inputClass} value={form.occupied} onChange={(e) => setForm({...form,occupied:e.target.value})} /></Field><Field label="Status"><select className={inputClass} value={form.status} onChange={(e) => setForm({...form,status:e.target.value})}><option>Available</option><option>Occupied</option><option>Maintenance</option></select></Field><Field label="Monthly fee"><input type="number" className={inputClass} value={form.monthly_fee} onChange={(e) => setForm({...form,monthly_fee:e.target.value})} /></Field></div>{error && <div className="mt-4 text-sm font-bold text-rose-600">{error}</div>}<div className="mt-6 flex justify-end gap-3"><SecondaryButton onClick={() => setModal(false)}>Cancel</SecondaryButton><PrimaryButton type="submit">Save room</PrimaryButton></div></form></Modal></>;
